export default JSON.parse("{\"schema\":\"ai-brain-source-note/1.0\",\"domain\":\"studio-tools\",\"capabilities\":[\"alignment\",\"class\",\"galaxy\",\"layer\"],\"provenance\":{\"sourceGroup\":\"player-reference-runtime-a\",\"sourceType\":\"provided-project-material\",\"archiveHash\":\"ff8940c1250d6e84\"},\"title\":\"readme.md\",\"content\":\"# Universal_Player\\n\\nUniversal_Player is the player-safe galaxy directory and lore browser. It exposes race, class, path, alignment, public deity, and approved generated-content records while intentionally omitting MOL-only Architect truth. It also includes browser-local lore notes and the preserved directory workbench.\\n\\n## Start\\nOpen `index.html`. For automatic cross-application updates, serve the shared `AI-Brain` parent folder as one origin.\\n\"}");
